import com.storyforge.platform.service.ScriptFetchService;

public class FetchTest {
    public static void main(String[] args) throws Exception {
        ScriptFetchService svc = new ScriptFetchService();
        // 200 case: body with trailing newline -> no trailing empty line
        String ok = svc.fetchContent("http://127.0.0.1:18099/ok.txt");
        System.out.println("OK=[" + ok + "]");
        // non-200 case
        try {
            svc.fetchContent("http://127.0.0.1:18099/missing");
            System.out.println("ERROR: no throw on 404");
        } catch (RuntimeException e) {
            System.out.println("404 threw: " + e.getClass().getSimpleName());
        }
        // blank case
        try {
            svc.fetchContent("  ");
            System.out.println("ERROR: no throw on blank");
        } catch (RuntimeException e) {
            System.out.println("blank threw: " + e.getClass().getSimpleName());
        }
        // null case
        try {
            svc.fetchContent(null);
            System.out.println("ERROR: no throw on null");
        } catch (RuntimeException e) {
            System.out.println("null threw: " + e.getClass().getSimpleName());
        }
        // unreachable case (connect timeout / refused)
        try {
            svc.fetchContent("http://127.0.0.1:19999/x");
            System.out.println("ERROR: no throw on refused");
        } catch (RuntimeException e) {
            System.out.println("refused threw: " + e.getClass().getSimpleName());
        }
    }
}
